def generate_usernames_from_email(apps, schema_editor):
    """Generate unique usernames for existing users based on their email."""
    User = apps.get_model('accounts', 'User')
    for user in User.objects.all():
        # Use email prefix as username base
        base_username = user.email.split('@')[0]
        username = base_username
        counter = 1

        # Ensure uniqueness
        while User.objects.filter(username=username).exclude(pk=user.pk).exists():
            username = f"{base_username}{counter}"
            counter += 1

        user.username = username
        user.save(update_fields=['username'])


def reverse_usernames(apps, schema_editor):
    """Reverse migration - clear usernames."""
    User = apps.get_model('accounts', 'User')
    User.objects.all().update(username='')


